export const saveAdminProductResponseOneBadgeArMax = 3000;

export const saveAdminProductResponseOneImagePathMax = 256;


export const saveAdminProductResponseOneImagePathRegExp = new RegExp('^(sprites/noir-product-grid\\.webp|[a-z0-9-]{2,60}/[a-f0-9]{32}\\.(jpg|png|webp))$');
export const saveAdminProductResponseOneVersionMin = 0;

export const saveAdminProductResponseOneVariantsItemPriceMin = 0.001;
export const saveAdminProductResponseOneVariantsItemPriceMax = 10000;

export const saveAdminProductResponseOneVariantsItemStockMin = 0;
export const saveAdminProductResponseOneVariantsItemStockMax = 100000;

export const saveAdminProductResponseOneVariantsMin = 2;
export const saveAdminProductResponseOneVariantsMax = 2;

export const saveAdminProductResponseTwoImageUrlMax = 2048;



export const SaveAdminProductResponse = zod.object({
  "id": zod.string().regex(saveAdminProductResponseOneIdRegExp),
  "name": zod.object({
  "en": zod.string().min(1).max(saveAdminProductResponseOneNameEnMax),
  "ar": zod.string().min(1).max(saveAdminProductResponseOneNameArMax)
}),
  "concentration": zod.object({
  "en": zod.string().min(1).max(saveAdminProductResponseOneConcentrationEnMax),
  "ar": zod.string().min(1).max(saveAdminProductResponseOneConcentrationArMax)
}),
  "description": zod.object({
  "en": zod.string().min(1).max(saveAdminProductResponseOneDescriptionEnMax),
  "ar": zod.string().min(1).max(saveAdminProductResponseOneDescriptionArMax)
}),
  "notes": zod.object({
  "top": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneNotesTopEnItemMax)).max(saveAdminProductResponseOneNotesTopEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneNotesTopArItemMax)).max(saveAdminProductResponseOneNotesTopArMax)
}),
  "heart": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneNotesHeartEnItemMax)).max(saveAdminProductResponseOneNotesHeartEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneNotesHeartArItemMax)).max(saveAdminProductResponseOneNotesHeartArMax)
}),
  "base": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneNotesBaseEnItemMax)).max(saveAdminProductResponseOneNotesBaseEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneNotesBaseArItemMax)).max(saveAdminProductResponseOneNotesBaseArMax)
})
}),
  "noteHighlights": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneNoteHighlightsEnItemMax)).max(saveAdminProductResponseOneNoteHighlightsEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneNoteHighlightsArItemMax)).max(saveAdminProductResponseOneNoteHighlightsArMax)
}),
  "audience": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneAudienceEnItemMax)).max(saveAdminProductResponseOneAudienceEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneAudienceArItemMax)).max(saveAdminProductResponseOneAudienceArMax)
}),
  "collections": zod.object({
  "en": zod.array(zod.string().max(saveAdminProductResponseOneCollectionsEnItemMax)).max(saveAdminProductResponseOneCollectionsEnMax),
  "ar": zod.array(zod.string().max(saveAdminProductResponseOneCollectionsArItemMax)).max(saveAdminProductResponseOneCollectionsArMax)
}),
  "badge": zod.object({
  "en": zod.string().min(1).max(saveAdminProductResponseOneBadgeEnMax),
  "ar": zod.string().min(1).max(saveAdminProductResponseOneBadgeArMax)
}).optional(),
  "imageKey": zod.enum(['oud', 'rose', 'amber', 'musk', 'night', 'bloom']),
  "imagePath": zod.string().max(saveAdminProductResponseOneImagePathMax).regex(saveAdminProductResponseOneImagePathRegExp).nullable(),
  "active": zod.boolean(),
  "version": zod.number().int().min(saveAdminProductResponseOneVersionMin),
  "variants": zod.array(zod.object({
  "size": zod.enum(['50ml', '100ml']),
  "price": zod.number().min(saveAdminProductResponseOneVariantsItemPriceMin).max(saveAdminProductResponseOneVariantsItemPriceMax),
  "stock": zod.number().int().min(saveAdminProductResponseOneVariantsItemStockMin).max(saveAdminProductResponseOneVariantsItemStockMax)
})).min(saveAdminProductResponseOneVariantsMin).max(saveAdminProductResponseOneVariantsMax)
}).and(zod.object({
  "imageUrl": zod.string().url().max(saveAdminProductResponseTwoImageUrlMax).nullable(),
  "updatedAt": zod.coerce.date().optional()
}))


/**
 * @summary Upload a product image to public Supabase Storage
 */
export const uploadAdminProductImagePathIdRegExp = new RegExp('^[a-z0-9-]{2,60}$');



export const UploadAdminProductImageParams = zod.object({
  "id": zod.coerce.string().regex(uploadAdminProductImagePathIdRegExp),
  "version": zod.coerce.number().int().min(1)
})

export const uploadAdminProductImageResponseImagePathMax = 256;

export const uploadAdminProductImageResponseImageUrlMax = 2048;




export const UploadAdminProductImageResponse = zod.object({
  "imagePath": zod.string().min(1).max(uploadAdminProductImageResponseImagePathMax),
  "imageUrl": zod.string().url().max(uploadAdminProductImageResponseImageUrlMax),
  "version": zod.number().int().min(1)
})


